function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 3 || s.length > 2000) return 's needs 3 to 2000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  return null;
}

