function checkPartitioning(s) {
  const n = s.length;
  const isPal = Array.from({ length: n }, () => new Array(n).fill(false));
  for (let start = n - 1; start >= 0; start--) {
    for (let end = start; end < n; end++) {
      if (s[start] === s[end] && (end - start < 2 || isPal[start + 1][end - 1])) {
        isPal[start][end] = true;
      }
    }
  }
  for (let firstEnd = 0; firstEnd < n - 2; firstEnd++) {
    if (!isPal[0][firstEnd]) {
      continue;
    }
    for (let secondEnd = firstEnd + 1; secondEnd < n - 1; secondEnd++) {
      if (isPal[firstEnd + 1][secondEnd] && isPal[secondEnd + 1][n - 1]) {
        return true;
      }
    }
  }
  return false;
}

