function checkPartitioning(s) {
  const pal = t => t === t.split('').reverse().join('');
  for (let i = 1; i < s.length; i++)
    for (let j = i + 1; j < s.length; j++)
      if (pal(s.slice(0, i)) && pal(s.slice(i, j)) && pal(s.slice(j))) return true;
  return false;
}

