function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alpha = size === 'large' ? 1 + Math.floor(rand() * 3) : 2 + Math.floor(rand() * 2);
  const letter = () => letters[Math.floor(rand() * alpha)];
  const palindrome = len => {
    const half = Array.from({ length: Math.ceil(len / 2) }, letter);
    const left = half.slice(0, Math.floor(len / 2));
    return half.join('') + left.reverse().join('');
  };
  const total = size === 'large' ? 1500 + Math.floor(rand() * 501) : 3 + Math.floor(rand() * 10);
  if (rand() < 0.4) {
    // Build a string that is three palindromes glued together, then sometimes break one letter.
    const a = 1 + Math.floor(rand() * (total - 2));
    const b = 1 + Math.floor(rand() * (total - a - 1));
    const chars = (palindrome(a) + palindrome(b) + palindrome(total - a - b)).split('');
    if (rand() < 0.3) chars[Math.floor(rand() * total)] = letters[Math.floor(rand() * 4)];
    return [chars.join('')];
  }
  return [Array.from({ length: total }, letter).join('')];
}
